-- key: entry
-- expect: procFlags = CASE WHEN `procFlags` <> 0 THEN `procFlags` ELSE (SELECT CASE WHEN m.`procFlags` >= 0 THEN m.`procFlags` ELSE t.`procFlags` END FROM ref.`srv_spell_template` t LEFT JOIN ref.`srv_spell_mod` m ON m.`Id` = t.`entry` WHERE t.`entry` = "srv_spell_proc_event"."entry") END
-- expect: CustomChance = CASE WHEN `CustomChance` <> 0 THEN `CustomChance` ELSE (SELECT CASE WHEN m.`procChance` >= 0 THEN m.`procChance` ELSE t.`procChance` END FROM ref.`srv_spell_template` t LEFT JOIN ref.`srv_spell_mod` m ON m.`Id` = t.`entry` WHERE t.`entry` = "srv_spell_proc_event"."entry") END
-- expect: SpellFamilyMask0 = CASE WHEN (CASE WHEN (SELECT m.`EffectApplyAuraName` FROM ref.`srv_spell_effect_mod` m WHERE m.`Id` = "srv_spell_proc_event"."entry" AND m.`EffectIndex` = 0) >= 0 THEN (SELECT m.`EffectApplyAuraName` FROM ref.`srv_spell_effect_mod` m WHERE m.`Id` = "srv_spell_proc_event"."entry" AND m.`EffectIndex` = 0) ELSE (SELECT t.`effectApplyAuraName1` FROM ref.`srv_spell_template` t WHERE t.`entry` = "srv_spell_proc_event"."entry") END) = 0 THEN 0 ELSE `SpellFamilyMask0` END
-- expect: SpellFamilyMask1 = CASE WHEN (CASE WHEN (SELECT m.`EffectApplyAuraName` FROM ref.`srv_spell_effect_mod` m WHERE m.`Id` = "srv_spell_proc_event"."entry" AND m.`EffectIndex` = 1) >= 0 THEN (SELECT m.`EffectApplyAuraName` FROM ref.`srv_spell_effect_mod` m WHERE m.`Id` = "srv_spell_proc_event"."entry" AND m.`EffectIndex` = 1) ELSE (SELECT t.`effectApplyAuraName2` FROM ref.`srv_spell_template` t WHERE t.`entry` = "srv_spell_proc_event"."entry") END) = 0 THEN 0 ELSE `SpellFamilyMask1` END
-- expect: SpellFamilyMask2 = CASE WHEN (CASE WHEN (SELECT m.`EffectApplyAuraName` FROM ref.`srv_spell_effect_mod` m WHERE m.`Id` = "srv_spell_proc_event"."entry" AND m.`EffectIndex` = 2) >= 0 THEN (SELECT m.`EffectApplyAuraName` FROM ref.`srv_spell_effect_mod` m WHERE m.`Id` = "srv_spell_proc_event"."entry" AND m.`EffectIndex` = 2) ELSE (SELECT t.`effectApplyAuraName3` FROM ref.`srv_spell_template` t WHERE t.`entry` = "srv_spell_proc_event"."entry") END) = 0 THEN 0 ELSE `SpellFamilyMask2` END
SELECT p.`entry` AS "entry", p.`SchoolMask` AS "SchoolMask", p.`SpellFamilyName` AS "SpellFamilyName", CASE WHEN f0.`Effect` IS NULL THEN 0 WHEN f0.`EffectAura` IN (107, 108, 109, 112) THEN p.`SpellFamilyMask0` ELSE (f0.`EffectSpellClassMask1` | (f0.`EffectSpellClassMask2` << 32)) END AS "SpellFamilyMask0", CASE WHEN f1.`Effect` IS NULL THEN 0 WHEN f1.`EffectAura` IN (107, 108, 109, 112) THEN p.`SpellFamilyMask1` ELSE (f1.`EffectSpellClassMask1` | (f1.`EffectSpellClassMask2` << 32)) END AS "SpellFamilyMask1", CASE WHEN f2.`Effect` IS NULL THEN 0 WHEN f2.`EffectAura` IN (107, 108, 109, 112) THEN p.`SpellFamilyMask2` ELSE (f2.`EffectSpellClassMask1` | (f2.`EffectSpellClassMask2` << 32)) END AS "SpellFamilyMask2", COALESCE(a.`ProcTypeMask1`, 0) AS "procFlags", p.`procEx` AS "procEx", COALESCE((SELECT r.`BaseProcRate` FROM `dbc_spellprocsperminute` r WHERE r.`ID` = a.`SpellProcsPerMinuteID`), 0) AS "ppmRate", COALESCE(a.`ProcChance`, 101) AS "CustomChance", COALESCE(a.`ProcCategoryRecovery`, 0) AS "Cooldown" FROM `spell_proc_event` p LEFT JOIN `dbc_spellauraoptions` a ON a.`SpellID` = p.`entry` AND a.`DifficultyID` = 0 LEFT JOIN `dbc_spelleffect` f0 ON f0.`SpellID` = p.`entry` AND f0.`DifficultyID` = 0 AND f0.`EffectIndex` = 0 AND f0.`Effect` <> 0 LEFT JOIN `dbc_spelleffect` f1 ON f1.`SpellID` = p.`entry` AND f1.`DifficultyID` = 0 AND f1.`EffectIndex` = 1 AND f1.`Effect` <> 0 LEFT JOIN `dbc_spelleffect` f2 ON f2.`SpellID` = p.`entry` AND f2.`DifficultyID` = 0 AND f2.`EffectIndex` = 2 AND f2.`Effect` <> 0
